import * as path from 'node:path';
import type { IFileSystem } from '@beyondnet/evolith-core';
import { McpTool } from '../mcp/tool.interface';

/**
 * `evolith-fixtures` — seed reproducible fixtures and sample data for demos and
 * tests. Mirrors the `evolith fixtures [type]` CLI command.
 *
 * The fixture *content* is generated by the same deterministic templates the CLI
 * command uses (there is no shared core-domain fixture service — the CLI defines
 * these inline). Files are written through the shared `IFileSystem` port from
 * `@beyondnet/evolith-core-domain`, i.e. the exact same adapter the CLI injects
 * via `@Inject('IFileSystem')`, so behaviour stays in lock-step across surfaces.
 *
 * Writes files → declared `mutative` / `scope: 'write'`. The dispatch therefore
 * requires `{ apply: true, approvalToken }` before execution.
 */

type FixtureType = 'demo' | 'adr' | 'ruleset' | 'evolith' | 'full';

interface FixtureFile {
  relativePath: string;
  content: string;
}

const VALID_TYPES: readonly FixtureType[] = ['demo', 'adr', 'ruleset', 'evolith', 'full'];

function generateEvolithFixtures(): FixtureFile[] {
  return [
    {
      relativePath: 'evolith.yaml',
      content: [
        'coreRef:',
        '  version: "1.0.0"',
        '  path: "../evolith"',
        'governance:',
        '  version: "1.0"',
        'product:',
        '  name: "demo-project"',
        '  type: "library"',
        'phases:',
        '  - "phase-0"',
        '  - "phase-1"',
        '  - "phase-2"',
        '',
      ].join('\n'),
    },
  ];
}

