function generateRulesetFixtures(): FixtureFile[] {
  return [
    {
      relativePath: 'rulesets/architecture.yaml',
      content: [
        'ruleset:',
        '  id: "architecture-conventions"',
        '  version: "1.0"',
        '  rules:',
        '    - id: "F1"',
        '      title: "Domain layer isolation"',
        '      description: "Domain layer must not depend on infrastructure"',
        '      severity: "error"',
        '    - id: "F2"',
        '      title: "Use case naming"',
        '      description: "Use cases must follow <Verb><Noun>UseCase pattern"',
        '      severity: "warning"',
        '',
      ].join('\n'),
    },
    {
      relativePath: 'rulesets/naming.yaml',
      content: [
        'ruleset:',
        '  id: "naming-conventions"',
        '  version: "1.0"',
        '  rules:',
        '    - id: "N1"',
        '      title: "File naming"',
        '      description: "Files must use kebab-case"',
        '      severity: "error"',
        '    - id: "N2"',
        '      title: "Class naming"',
        '      description: "Classes must use PascalCase"',
        '      severity: "error"',
        '',
      ].join('\n'),
    },
  ];
}

function generateFixtures(type: FixtureType): FixtureFile[] {
  switch (type) {
    case 'evolith':
      return generateEvolithFixtures();
    case 'adr':
      return generateAdrFixtures();
    case 'ruleset':
      return generateRulesetFixtures();
    case 'demo':
      return [...generateEvolithFixtures(), ...generateAdrFixtures()];
    case 'full':
      return [...generateEvolithFixtures(), ...generateAdrFixtures(), ...generateRulesetFixtures()];
  }
}

/** Fixture seeding tool (single operation, mirrors `evolith fixtures [type]`). */
export function createFixturesTools(fs: IFileSystem): McpTool[] {
  return [
    {
      mutative: true,
      scope: 'write' as const,
      schema: {
        name: 'evolith-fixtures',
        description:
          'Seed reproducible fixtures and sample data (evolith.yaml, ADRs, rulesets) for demos and tests. Mirrors the "evolith fixtures" CLI command.',
        inputSchema: {
          type: 'object',
          properties: {
            type: {
              type: 'string',
              description: 'Fixture type to generate: demo, adr, ruleset, evolith, full',
              enum: ['demo', 'adr', 'ruleset', 'evolith', 'full'],
              default: 'demo',
            },
            dir: {
              type: 'string',
              description: 'Target directory for fixtures (defaults to the current working directory)',
            },
            dryRun: {
              type: 'boolean',
              description: 'Preview the files that would be written without touching the filesystem',
              default: false,
            },
          },
          required: [],
        },
      },
      execute: async (args: Record<string, unknown>): Promise<unknown> => {
        const fixtureType = ((args.type as string) || 'demo') as FixtureType;
        const targetDir = (args.dir as string) || process.cwd();
        const dryRun = Boolean(args.dryRun);

        if (!VALID_TYPES.includes(fixtureType)) {
          throw new Error(
            `Invalid fixture type: ${fixtureType}. Valid types: ${VALID_TYPES.join(', ')}`,
          );
        }

        const files = generateFixtures(fixtureType);

        if (dryRun) {
          // Return the raw payload only — the dispatch wraps it in the canonical
          // ADR-0073 output envelope { success, data, meta }.
          return {
            type: fixtureType,
            targetDir,
            dryRun: true,
            created: files.map((f) => f.relativePath),
          };
        }

        const created: string[] = [];
        const errors: Array<{ file: string; message: string }> = [];

        for (const file of files) {
          try {
            const fullPath = path.join(targetDir, file.relativePath);
            await fs.ensureDir(path.dirname(fullPath));
            await fs.writeFile(fullPath, file.content);
            created.push(file.relativePath);
          } catch (err) {
            const message = err instanceof Error ? err.message : String(err);
            errors.push({ file: file.relativePath, message });
          }
        }

        if (errors.length > 0) {
          // Surface IO failures as a thrown error so the dispatch maps it to the
          // ADR-0073 error envelope (mirrors the CLI's IO_ERROR exit path).
          const detail = errors.map((e) => `${e.file}: ${e.message}`).join('; ');
          throw new Error(
            `Failed to write ${errors.length} of ${files.length} fixture file(s): ${detail}`,
          );
        }

        return {
          type: fixtureType,
          targetDir,
          dryRun: false,
          created,
        };
      },
    },
  ];
}
